import{_ as e,o,c as r,a2 as t}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1793876064000}'),d={name:"guide/faq.md"};function i(l,a,n,c,s,h){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="保存组件后为什么没有生效" tabindex="-1">保存组件后为什么没有生效？ <a class="header-anchor" href="#保存组件后为什么没有生效" aria-label="Permalink to &quot;保存组件后为什么没有生效？&quot;">​</a></h2><p>确认「设置 → 扩展」中该组件已启用；如果仍不生效，点击「设置 → 扩展」里的热加载或重新加载应用，并查看扩展列表中的错误信息。</p><h2 id="组件里的样式不跟随主题" tabindex="-1">组件里的样式不跟随主题？ <a class="header-anchor" href="#组件里的样式不跟随主题" aria-label="Permalink to &quot;组件里的样式不跟随主题？&quot;">​</a></h2><p>不要写死颜色。使用 <code>var(--el-bg-color)</code>、<code>var(--el-text-color-primary)</code> 等 Element Plus 变量，并避免在组件根节点上设置不透明背景。</p><h2 id="可以-import-npm-包吗" tabindex="-1">可以 import npm 包吗？ <a class="header-anchor" href="#可以-import-npm-包吗" aria-label="Permalink to &quot;可以 import npm 包吗？&quot;">​</a></h2><p>只支持文档中列出的运行时模块。其他依赖请先放到 <code>resources/js</code> 并以全局变量形式使用，或改成资源目录内的 ES Module。</p><h2 id="插件脚本的执行顺序" tabindex="-1">插件脚本的执行顺序？ <a class="header-anchor" href="#插件脚本的执行顺序" aria-label="Permalink to &quot;插件脚本的执行顺序？&quot;">​</a></h2><p>按文件名排序串行加载。需要明确顺序时使用数字前缀，例如 <code>01-init.js</code>、<code>02-search.js</code>。</p><h2 id="修改资源后需要重新构建客户端吗" tabindex="-1">修改资源后需要重新构建客户端吗？ <a class="header-anchor" href="#修改资源后需要重新构建客户端吗" aria-label="Permalink to &quot;修改资源后需要重新构建客户端吗？&quot;">​</a></h2><p>不需要。外部组件保存后热加载；插件脚本和样式重新加载应用即可生效。只有修改客户端本身的 Vue 源码才需要重新构建。</p>',11)])])}const u=e(d,[["render",i]]);export{m as __pageData,u as default};
